int canvasWidth = 700;
int canvasHeight = 700;

int characterWidth = 90;
int characterHeight = 90;

int characterX = (canvasWidth - characterWidth) / 2;
int characterY = (canvasHeight - characterHeight) / 2;

color backgroundColor = color(0, 255, 0);

int obstacleWidth = 70;
int obstacleHeight = 70;

int obstacle1X = (int)random(canvasWidth - obstacleWidth);
int obstacle1Y = (int)random(canvasHeight - obstacleHeight);
int obstacle2X = (int)random(canvasWidth - obstacleWidth);
int obstacle2Y = (int)random(canvasHeight - obstacleHeight);

void setup() {
  size(canvasWidth, canvasHeight);
}

void draw() {
  // Draw background
  background(backgroundColor);

  // Draw character
  fill(255);
  stroke(0);
  rect(characterX, characterY, characterWidth, characterHeight);
  triangle(characterX, characterY, characterX + characterWidth, characterY, characterX + characterWidth / 2, characterY - characterHeight / 2);

  // Update character position
  if (keyPressed) {
    if (keyCode == UP) {
      characterY -= characterHeight;
    } else if (keyCode == DOWN) {
      characterY += characterHeight;
    } else if (keyCode == LEFT) {
      characterX -= characterWidth;
    } else if (keyCode == RIGHT) {
      characterX += characterWidth;
    }
  }

  // Wrap character around the canvas
  if (characterX > canvasWidth) {
    characterX = 0;
  } else if (characterX + characterWidth < 0) {
    characterX = canvasWidth - characterWidth;
  }
  if (characterY > canvasHeight) {
    characterY = 0;
  } else if (characterY + characterHeight < 0) {
    characterY = canvasHeight - characterHeight;
  }

  // Draw trail
  stroke(255);
  line(characterX + characterWidth / 2, characterY, characterX + characterWidth / 2, 0);

  // Draw obstacles
  fill(255, 0, 0);
  rect(obstacle1X, obstacle1Y, obstacleWidth, obstacleHeight);
  rect(obstacle2X, obstacle2Y, obstacleWidth, obstacleHeight);

  // Check for collisions with obstacles
  if (collidesWithObstacle(characterX, characterY, characterWidth, characterHeight, obstacle1X, obstacle1Y, obstacleWidth, obstacleHeight) || collidesWithObstacle(characterX, characterY, characterWidth, characterHeight, obstacle2X, obstacle2Y, obstacleWidth, obstacleHeight)) {
    gameOver();
  }
}

// Detect collision between two rectangles
boolean collidesWithObstacle(int x1, int y1, int w1, int h1, int x2, int y2, int w2, int h2) {
  return x1 < x2 + w2 &&
         x1 + w1 > x2 &&
         y1 < y2 + h2 &&
         y1 + h1 > y2;
}

void gameOver() {
  background(0);
  fill(255);
  textAlign(CENTER, CENTER);
  textSize(50);
  text("Game Over", canvasWidth / 2, canvasHeight / 2);
  noLoop();
}
